    if(isSla&&d.rank){rankEl.textContent=d.rank;rankEl.style.display='inline-block';}
    else if(isDem&&d.demon_tier){
      rankEl.textContent=d.demon_tier;rankEl.style.display='inline-block';
      rankEl.style.background='rgba(200,48,64,.1)';rankEl.style.borderColor='rgba(200,48,64,.25)';rankEl.style.color='#e06070';
    }

    // stats
    var st=d.stats||{};
    ['str','spd','stm','int','wil','sen'].forEach(function(k){KNYc.setBar(k,st[k])});

    // power
    var powWrap=document.getElementById('pow-wrap');
    var powGem=document.getElementById('pow-gem');
    var powTitle=document.getElementById('pow-title');
    var powPanel=document.getElementById('pow-panel');
    var powLbl=document.getElementById('pow-lbl');
    var powName=document.getElementById('pow-name');
    var powSub=document.getElementById('pow-sub');
    var powChip=document.getElementById('pow-chip');
    var powWeak=document.getElementById('pow-weak');
    if(isSla&&d.breathing_style&&d.breathing_style!=='None'){
      powWrap.style.display='block';
      powTitle.textContent='Breathing Style';
      powLbl.textContent='Style';
      powName.textContent=d.breathing_style;
      if(d.breathing_forms){powSub.textContent=d.breathing_forms;}
      if(d.nichirin_colour){powChip.textContent='Nichirin: '+d.nichirin_colour;powChip.style.display='inline-block';}
    } else if(isDem&&d.blood_demon_art){
      powWrap.style.display='block';
      powGem.style.background='#c83040';
      powTitle.style.color='#c83040';powTitle.textContent='Blood Demon Art';
      powPanel.classList.add('dem-panel');
      powLbl.style.color='#c83040';powLbl.textContent='Art';
      powName.textContent=d.blood_demon_art;
      if(d.blood_demon_art_desc)powSub.textContent=d.blood_demon_art_desc;
      if(d.blood_demon_art_weakness){powWeak.textContent='⊘ '+d.blood_demon_art_weakness;powWeak.style.display='block';}
    }

    // skills
    var skills=d.skills||[];
    var wrap=document.getElementById('cn-skills');
    if(skills.length){
      wrap.innerHTML='';
      skills.forEach(function(sk){
        var tag=nameToTag(sk);
        var chip=document.createElement('span');
        chip.className='sk-chip sk-'+tag;
        chip.textContent=sk;
        wrap.appendChild(chip);
      });
    }

    // quote
    if(d.quote&&d.quote.trim()){
      document.getElementById('cn-quote').textContent='"'+d.quote+'"';
      document.getElementById('cn-qname').textContent=d.name||'';
      document.getElementById('cn-quote-wrap').style.display='block';
    }

    // trio
    KNYc.setTxt('cn-goal',d.goal,'—');
    KNYc.setTxt('cn-fate',d.fate,'—');
    KNYc.setTxt('cn-bond',d.bond,'—');

    // lore
    KNYc.setTxt('cn-appear',d.appearance,'Not provided');
    KNYc.setTxt('cn-pers',d.personality,'Not provided');
    KNYc.setTxt('cn-bg',d.background,'Not provided');
    KNYc.setTxt('cn-secret',d.secret,'Not provided');
    KNYc.setTxt('cn-extra',d.extra,'Not provided');
  }
};

document.addEventListener('DOMContentLoaded',KNYc.init);
if(document.readyState!=='loading')KNYc.init();
</script>
